import{_ as s,o as i,c as a,a3 as n}from"./chunks/framework.Ch_0qWu9.js";const m=JSON.parse('{"title":"Lean task environment","description":"","frontmatter":{"sourcePath":"assets/environments/lean-base/README.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/environments/lean-base/README.md","alternateUrl":"/TCSExam/docs/zh/environments/lean-base/","alternateAnchors":{"lean-task-environment":"lean-task-environment","running-and-judging":"running-and-judging","source-and-license-materials":"source-and-license-materials"}},"headers":[],"relativePath":"environments/lean-base/index.md","filePath":"environments/lean-base/index.md"}'),t={name:"environments/lean-base/index.md"};function o(r,e,d,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="lean-task-environment" tabindex="-1">Lean task environment <a class="header-anchor" href="#lean-task-environment" aria-label="Permalink to &quot;Lean task environment&quot;">​</a></h1><p>This guide explains how to build and use the shared Lean environment.</p><p>The environment targets Linux <code>amd64</code>. Install Harbor <code>0.22.0</code> for task execution. Lean uses <code>leanprover/lean4:v4.33.0-rc1</code>; mathlib is pinned to commit <code>5b3f719bf129e3cf48daf6ff76a2ec5cb6e9b1e3</code> and installed at <code>/opt/lean-lib/mathlib4</code>. Elan selects the Lean toolchain and Lake manages its dependencies. The fixed transitive dependencies are listed in <code>mathlib-lake-manifest.json</code>.</p><p>From the repository root, prepare the fixed public source archives and build the selected tasks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> theorem</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> theorem</span></span></code></pre></div><p><code>source-inputs</code> verifies the Graphviz and wrapper archives declared in <code>graphviz-epl/source-manifest.json</code> before placing them in the build context. If an upstream download is unavailable, supply an identical local archive through the explicit import documented in the <a href="/TCSExam/docs/resources/#prepare-fixed-lean-source-archives">resource guide</a>. Source preparation does not compile Lean or build Docker images.</p><p>Use the complete directory as the base-image build context. The Dockerfile pins its Ubuntu image, Elan archive and mathlib commit. Build-time dependency retrieval requires network access; failed retrieval stops the build. Host networking during the build does not change the selected task&#39;s runtime network policy. Local products and historical image records keep separate identities.</p><p>Reserve at least 40 GB of disk for image layers, compiled libraries, task builds and logs. Lean tasks use 4 CPU cores and 16 GB of memory; consult the selected <code>task.toml</code> for storage and compilation limits. The development budget is twelve hours (43,200 seconds). Environment build, agent installation and final judging have separate budgets. External runtime timeout multipliers remain <code>1</code>.</p><p>The base image makes compiled mathlib files readable by non-root users. Each development image copies only its task&#39;s <code>environment/app/</code> and performs the task&#39;s declared installation. Complete installation before invoking Lean in a new project, so Lake can resolve the pinned dependency configuration. Runtime connectivity follows each task&#39;s configuration.</p><h2 id="running-and-judging" tabindex="-1">Running and judging <a class="header-anchor" href="#running-and-judging" aria-label="Permalink to &quot;Running and judging&quot;">​</a></h2><p>Retain Harbor&#39;s native task entry points. See the <a href="https://docs.harborframework.com/tasks/overview" target="_blank" rel="noreferrer">Harbor task documentation</a> and the repository <a href="/TCSExam/docs/running/">running guide</a>. Generate a configuration without invoking a model or compiling Lean:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> theorem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://YOUR_PROVIDER.example/v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/theorem.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcsexam.harbor_launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/theorem.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print-config</span></span></code></pre></div><p>The independent verifier uses the development image from the same task and the original <code>tests/</code> files. The development build context excludes <code>tests/</code>, <code>solution/</code> and historical complete proofs. Keep these materials outside the model-solving environment.</p><p>Retain the task&#39;s reference statements, editable ranges, axiom checks and scoring files. Theorem tasks use their declared standard axioms; construction tasks use the computational axioms listed in <code>judge.json</code>. Open-conjecture tasks judge their two main statements independently. Compilation and judging limits apply to every submission.</p><p>Run <code>tcsexam validate</code> for static repository checks. It does not compile Lean. After changing the task inventory, regenerate declarations with <code>PYTHONPATH=src python -m tcsexam.lean_recipes</code>, or append <code>--check</code> to detect stale fields.</p><h2 id="source-and-license-materials" tabindex="-1">Source and license materials <a class="header-anchor" href="#source-and-license-materials" aria-label="Permalink to &quot;Source and license materials&quot;">​</a></h2><p>The Dockerfile installs <code>NOTICE.md</code> at <code>/usr/share/doc/tcsexam/README.md</code> and retains the following separate material sets:</p><ul><li><code>lean-components/</code>: fixed Lake component commits and original licenses.</li><li><code>graphviz-epl/</code>: Graphviz EPL-2.0 text, source offer, fixed source archives, wrapper modifications and build rules.</li><li><code>browser-components/</code>: Expat, Emscripten and Penrose notices with their stated dependency scope.</li><li><code>proofwidgets-npm/</code>: fixed npm dependency source records and original or clearly identified supplementary licenses.</li></ul><p>Keep the material paths and their checksum checks in rebuilt images. Each dependency retains its own terms; a project license does not replace a third-party license. Dependency inventories may include build-only components and do not imply that every listed component is linked into the browser payload. See the <a href="/TCSExam/docs/licenses/distribution/">distribution guide</a>.</p><p>Task provenance is recorded in <code>assets/sources.json</code>, shared dependency pins in <code>pins.json</code>, and resource preparation requirements in the <a href="/TCSExam/docs/resources/">resource guide</a>. <code>tcsexam doctor</code> reports local image availability separately from runtime acceptance.</p>`,20)])])}const k=s(t,[["render",o]]);export{m as __pageData,k as default};
